package com.example.starter.calibration.model;

/**
 * 校准证书类型。
 */
public enum CertType {

    /** 线性证书：校正值 = a×读数 + b，走原单测量提交流程。 */
    LINEAR,

    /** 迟滞证书：校正值 = 斜率×读数 + 方向偏移（上升/下降），走校准会话流程。 */
    HYSTERESIS
}

package com.example.starter.calibration.model;

/**
 * 读数变化方向（迟滞校准）。
 */
public enum Direction {

    /** 上升：读数较上一条增大，或首条显式声明上升；使用上升偏移。 */
    UP,

    /** 下降：读数较上一条减小，或首条显式声明下降；使用下降偏移。 */
    DOWN
}

package com.example.starter.calibration.model;

/**
 * 校准会话状态。
 */
public enum SessionStatus {

    /** 追加中：可继续顺序追加条目。 */
    OPEN,

    /** 已关闭：方向与精确结果冻结，不再追加；可被批量放行引用。 */
    CLOSED,

    /** 已放行：经会话批量放行原子放行，全部成员测量转为已放行。 */
    RELEASED
}

